                'onus.tipo_ont_id AS tipo_ont_id, onus.line_profile_id AS line_profile_id, onus.plan_id AS '
                'plan_id, onus.plan_velocidad AS plan_velocidad, onus.estado AS estado, onus.rx_power_dbm AS '
                'rx_power_dbm, onus.tx_power_dbm AS tx_power_dbm, onus.distancia_m AS distancia_m, '
                'onus.ultima_lectura AS ultima_lectura, onus.created_at AS created_at, onus.causa_caida AS '
                'causa_caida, onus.causa_caida_cruda AS causa_caida_cruda, onus.ultima_caida AS '
                'ultima_caida, onus.autorizada_at AS autorizada_at, onus.zona AS zona, '
                'onus.optica_registrada_at AS optica_registrada_at, onus.modelo AS modelo, onus.vlan AS '
                'vlan, onus.descripcion_olt AS descripcion_olt, PG_DESCIFRAR(onus.direccion) AS direccion, '
                'onus.contacto AS contacto, onus.odb AS odb, onus.line_profile_olt AS line_profile_olt, '
                'onus.srv_profile_olt AS srv_profile_olt, onus.srv_profile_nombre AS srv_profile_nombre, '
