                        'PG_DESCIFRAR(instalaciones.nombre) AS nombre, instalaciones.tipo_identificacion AS '
                        'tipo_identificacion, PG_DESCIFRAR(instalaciones.identificacion) AS identificacion, '
                        'PG_DESCIFRAR(instalaciones.telefono) AS telefono, '
                        'PG_DESCIFRAR(instalaciones.telefono_whatsapp) AS telefono_whatsapp, '
                        'PG_DESCIFRAR(instalaciones.email) AS email, PG_DESCIFRAR(instalaciones.referencia) '
                        'AS referencia, instalaciones.sector AS sector, instalaciones.canton AS canton, '
                        'instalaciones.tecnologia AS tecnologia, instalaciones.factibilidad AS factibilidad, '
                        'instalaciones.factibilidad_notas AS factibilidad_notas, '
