                        'instalaciones.ruta_fecha AS ruta_fecha, instalaciones.ruta_orden AS ruta_orden FROM '
                        'instalaciones AS instalaciones WHERE NOT RLS_ACTIVA() OR (((SELECT COALESCE((SELECT '
                        "PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR "
                        "PG_JSON_TIENE(usuarios_sistema.permisos, 'clientes.cartera') AS _col_0 FROM "
                        'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                        'AND usuarios_sistema.activo LIMIT 1), TRUE /* Sin legajo no se bloquea a nadie: es '
                        'una instalación que todavía no */ /* corrió la migración 66, y cerrarle el paso la '
                        'dejaría inutilizable de */ /* golpe. El frente se comporta igual por la misma '
                        'razón. */) AS _col_0) OR (instalaciones.tecnico_id IS NOT NULL AND '
                        'instalaciones.tecnico_id = (SELECT usuarios_sistema.tecnico_id AS tecnico_id FROM '
                        'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                        'AND usuarios_sistema.activo LIMIT 1)) OR instalaciones.client_id IN (SELECT '
                        'cliente_id AS cliente_id FROM (WITH yo AS (SELECT usuarios_sistema.id AS id, '
                        'usuarios_sistema.tecnico_id AS tecnico_id FROM usuarios_sistema AS usuarios_sistema '
                        'WHERE usuarios_sistema.auth_id = AUTH_UID() AND usuarios_sistema.activo LIMIT 1) /* '
                        'Solo el técnico y los clientes de sus trabajos. */ /* La cobranza SALIÓ de acá a '
                        'propósito: abría la ficha completa cuando lo */ /* que hace falta es un nombre, un '
                        'teléfono y un saldo. Va por */ /* `v_cobros_por_gestionar`, más abajo. */ SELECT '
                        't_fn659.client_id AS cliente_id FROM tickets AS t_fn659 JOIN yo AS yo ON '
                        't_fn659.tecnico_id = yo.tecnico_id WHERE t_fn659.client_id IS NOT NULL UNION SELECT '
                        'i_fn659.client_id AS client_id FROM instalaciones AS i_fn659 JOIN yo AS yo ON '
                        'i_fn659.tecnico_id = yo.tecnico_id WHERE i_fn659.client_id IS NOT NULL) AS _0)) OR '
                        "((SELECT COALESCE((SELECT PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR "
                        "PG_JSON_TIENE(usuarios_sistema.permisos, 'clientes.cartera') AS _col_0 FROM "
                        'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                        'AND usuarios_sistema.activo LIMIT 1), TRUE /* Sin legajo no se bloquea a nadie: es '
                        'una instalación que todavía no */ /* corrió la migración 66, y cerrarle el paso la '
                        'dejaría inutilizable de */ /* golpe. El frente se comporta igual por la misma '
                        'razón. */) AS _col_0) OR (instalaciones.tecnico_id IS NOT NULL AND '
                        'instalaciones.tecnico_id = (SELECT usuarios_sistema.tecnico_id AS tecnico_id FROM '
                        'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                        'AND usuarios_sistema.activo LIMIT 1))) OR (instalaciones.id IN (SELECT '
                        'pr.instalacion_id AS instalacion_id FROM (SELECT prospectos.id AS id, '
                        'PG_DESCIFRAR(prospectos.nombre) AS nombre, PG_DESCIFRAR(prospectos.identificacion) '
                        'AS identificacion, PG_DESCIFRAR(prospectos.telefono) AS telefono, '
                        'PG_DESCIFRAR(prospectos.telefono_whatsapp) AS telefono_whatsapp, '
                        'PG_DESCIFRAR(prospectos.email) AS email, PG_DESCIFRAR(prospectos.direccion) AS '
                        'direccion, PG_DESCIFRAR(prospectos.referencia) AS referencia, prospectos.sector AS '
                        'sector, prospectos.canton AS canton, prospectos.latitud AS latitud, '
                        'prospectos.longitud AS longitud, prospectos.plan_id AS plan_id, prospectos.origen '
                        'AS origen, prospectos.estado AS estado, prospectos.motivo_perdida AS '
                        'motivo_perdida, prospectos.vendedor_id AS vendedor_id, prospectos.cobertura AS '
                        'cobertura, prospectos.nap_id AS nap_id, prospectos.distancia_nodo_m AS '
                        'distancia_nodo_m, prospectos.proxima_accion AS proxima_accion, '
                        'prospectos.instalacion_id AS instalacion_id, prospectos.cliente_id AS cliente_id, '
                        'prospectos.notas AS notas, prospectos.creado_por AS creado_por, '
                        'prospectos.creado_en AS creado_en, prospectos.actualizado_en AS actualizado_en, '
                        'prospectos.archivado_en AS archivado_en, prospectos.ganado_en AS ganado_en, '
                        'prospectos.promocion_id AS promocion_id, prospectos.tipo_operacion AS '
                        'tipo_operacion FROM prospectos AS prospectos WHERE NOT RLS_ACTIVA() OR (((SELECT '
                        "COALESCE((SELECT PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR "
                        "PG_JSON_TIENE(usuarios_sistema.permisos, 'clientes.cartera') AS _col_0 FROM "
                        'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                        'AND usuarios_sistema.activo LIMIT 1), TRUE /* Sin legajo no se bloquea a nadie: es '
                        'una instalación que todavía no */ /* corrió la migración 66, y cerrarle el paso la '
