                     'd.descripcion AS descripcion, d.mac_address AS mac_address, d.origen AS origen, '
                     'd.visto_at AS visto_at, s.nombre AS subred, s.cidr AS cidr, s.tipo AS subred_tipo, '
                     "c.nombre AS cliente, c.estado AS estado_cliente, (d.origen = 'arp' AND d.client_id IS "
                     'NULL) AS sin_autorizar FROM ip_addresses AS d LEFT JOIN subredes AS s ON s.id = '
                     'd.subred_id LEFT JOIN (SELECT clientes.id AS id, PG_DESCIFRAR(clientes.nombre) AS '
                     'nombre, clientes.router_id AS router_id, clientes.onu_id AS onu_id, clientes.plan_id '
