                  'subido_en, expediente_documentos.validado_por AS validado_por, '
                  'expediente_documentos.validado_en AS validado_en, expediente_documentos.notas AS notas '
                  'FROM expediente_documentos AS expediente_documentos WHERE NOT RLS_ACTIVA() OR '
                  '((expediente_documentos.expediente_id IN (SELECT expedientes.id AS id FROM (SELECT '
                  'expedientes.id AS id, expedientes.prospecto_id AS prospecto_id, expedientes.contrato_id '
                  'AS contrato_id, expedientes.instalacion_id AS instalacion_id, expedientes.cliente_id AS '
                  'cliente_id, expedientes.datos_confirmados_en AS datos_confirmados_en, expedientes.latitud '
                  'AS latitud, expedientes.longitud AS longitud, expedientes.precision_m AS precision_m, '
                  'expedientes.ubicacion_origen AS ubicacion_origen, expedientes.ubicacion_en AS '
                  'ubicacion_en, expedientes.ubicacion_por AS ubicacion_por, expedientes.estado AS estado, '
                  'expedientes.enviado_en AS enviado_en, expedientes.notas AS notas, expedientes.creado_por '
                  'AS creado_por, expedientes.creado_en AS creado_en, expedientes.actualizado_en AS '
                  'actualizado_en FROM expedientes AS expedientes WHERE NOT RLS_ACTIVA() OR '
                  '((expedientes.prospecto_id IN (SELECT prospectos.id AS id FROM (SELECT prospectos.id AS '
                  'id, PG_DESCIFRAR(prospectos.nombre) AS nombre, PG_DESCIFRAR(prospectos.identificacion) AS '
                  'identificacion, PG_DESCIFRAR(prospectos.telefono) AS telefono, '
                  'PG_DESCIFRAR(prospectos.telefono_whatsapp) AS telefono_whatsapp, '
                  'PG_DESCIFRAR(prospectos.email) AS email, PG_DESCIFRAR(prospectos.direccion) AS direccion, '
                  'PG_DESCIFRAR(prospectos.referencia) AS referencia, prospectos.sector AS sector, '
                  'prospectos.canton AS canton, prospectos.latitud AS latitud, prospectos.longitud AS '
                  'longitud, prospectos.plan_id AS plan_id, prospectos.origen AS origen, prospectos.estado '
                  'AS estado, prospectos.motivo_perdida AS motivo_perdida, prospectos.vendedor_id AS '
