                          'nodos_red.monitorear AS monitorear, nodos_red.avisar AS avisar, nodos_red.estado '
                          'AS estado, nodos_red.latencia_ms AS latencia_ms, nodos_red.perdida_pct AS '
                          'perdida_pct, nodos_red.desde AS desde, nodos_red.ultimo_chequeo AS '
                          'ultimo_chequeo, nodos_red.notas AS notas, nodos_red.created_at AS created_at, '
                          'nodos_red.updated_at AS updated_at, nodos_red.numero AS numero, nodos_red.equipo '
                          'AS equipo FROM nodos_red AS nodos_red WHERE NOT RLS_ACTIVA() OR (((SELECT '
                          "COALESCE((SELECT PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR "
                          "PG_JSON_TIENE(usuarios_sistema.permisos, 'red.monitoreo') AS _col_0 FROM "
                          'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                          'AND usuarios_sistema.activo LIMIT 1), TRUE) AS _col_0)) OR ((SELECT '
                          "COALESCE((SELECT PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR "
                          "PG_JSON_TIENE(usuarios_sistema.permisos, 'red.monitoreo') AS _col_0 FROM "
                          'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() '
                          'AND usuarios_sistema.activo LIMIT 1), TRUE) AS _col_0)))) AS n ON n.id = '
                          'i.nodo_id LEFT JOIN olts AS o ON o.id = i.olt_id LEFT JOIN routers_mikrotik AS r '
                          'ON r.id = i.router_id',
