               'AS avisos_baja_at, clientes.avisos_baja_texto AS avisos_baja_texto, clientes.descuento_fijo '
               'AS descuento_fijo, clientes.descuento_fijo_motivo AS descuento_fijo_motivo, '
               'clientes.ipv6_prefijo AS ipv6_prefijo, clientes.acepta_datos_personales AS '
