                  'senal_critica, ROUND(CAST(AVG(u.rx_power_dbm) AS REAL), 2) AS rx_promedio, '
                  'MIN(u.rx_power_dbm) AS rx_peor, (COUNT(*) > 1 AND COUNT(*) FILTER(WHERE u.estado = '
