                 'prospectos.cliente_id AS cliente_id, prospectos.notas AS notas, prospectos.creado_por AS '
                 'creado_por, prospectos.creado_en AS creado_en, prospectos.actualizado_en AS '
                 'actualizado_en, prospectos.archivado_en AS archivado_en, prospectos.ganado_en AS '
                 'ganado_en, prospectos.promocion_id AS promocion_id, prospectos.tipo_operacion AS '
                 'tipo_operacion FROM prospectos AS prospectos WHERE NOT RLS_ACTIVA() OR (((SELECT '
                 "COALESCE((SELECT PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR "
                 "PG_JSON_TIENE(usuarios_sistema.permisos, 'clientes.cartera') AS _col_0 FROM "
                 'usuarios_sistema AS usuarios_sistema WHERE usuarios_sistema.auth_id = AUTH_UID() AND '
                 'usuarios_sistema.activo LIMIT 1), TRUE /* Sin legajo no se bloquea a nadie: es una '
                 'instalación que todavía no */ /* corrió la migración 66, y cerrarle el paso la dejaría '
                 'inutilizable de */ /* golpe. El frente se comporta igual por la misma razón. */) AS '
                 '_col_0) OR (prospectos.archivado_en IS NULL AND ((SELECT COALESCE((SELECT '
                 "PG_JSON_TIENE(usuarios_sistema.permisos, '*') OR PG_JSON_TIENE(usuarios_sistema.permisos, "
                 "'ventas.equipo') AS _col_0 FROM usuarios_sistema AS usuarios_sistema WHERE "
                 'usuarios_sistema.auth_id = AUTH_UID() AND usuarios_sistema.activo LIMIT 1), TRUE /* Sin '
                 'legajo se permite, igual que el resto de los ayudantes: una */ /* instalación sin la '
