                 'AS created_at, COALESCE(u.clientes, 0) AS clientes, CASE WHEN pr.capacidad IS NULL THEN '
                 'NULL ELSE pr.capacidad - COALESCE(u.clientes, 0) END AS disponibles FROM puntos_red AS pr '
                 'LEFT JOIN (SELECT clientes.nap_id AS nap_id, COUNT(*) AS clientes FROM (SELECT clientes.id '
