                     't_fn48.client_id IS NOT NULL UNION SELECT i_fn48.client_id AS client_id FROM '
                     'instalaciones AS i_fn48 JOIN yo AS yo ON i_fn48.tecnico_id = yo.tecnico_id WHERE '
                     'i_fn48.client_id IS NOT NULL) AS _1)))) AS pagos WHERE NOT pagos.anulado GROUP BY '
                     'pagos.client_id) AS pg ON pg.client_id = c.id',
